///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/stockisu.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst90007.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.reflectCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reflectCorpName = function () {
    /* sdd-asis-lifecycle:begin reflectCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let nm = $c.util.getComponent('ipt_stockIsuNm').getValue();
    nm = encodeURI(nm);
    $c.util.getComponent('ipt_stockIsuNm').setValue(nm);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.setCodeName();
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("marketType", "#marketType");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "findStockIsu");
    $c.util.getComponent('ipt_beginIndex').setValue("");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setStockInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_marketType isuSrtCd isuEngAbbrv isuCd indNm listDd
 * @returns
 * @hidden N
*/
scwin.setStockInfo = function (ipt_marketType, isuSrtCd, isuEngAbbrv, isuCd, indNm, listDd) {
    /* sdd-asis-lifecycle:begin setStockInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).setStockInfo === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).setStockInfo(ipt_marketType, isuSrtCd, isuEngAbbrv, isuCd, indNm, listDd) : void 0), $c.win.closePopup([ipt_marketType, isuSrtCd, isuEngAbbrv, isuCd, indNm, listDd]));
    this.close();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCodeName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setCodeName = function () {
    /* sdd-asis-lifecycle:begin setCodeName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_stockIsuCd').setValue("");
    $c.util.getComponent('ipt_stockIsuNm').setValue("");
    let stockIsu = $c.util.getComponent('ipt_stockIsu').getValue(); if (stockIsu == null) { stockIsu = ''; }
    stockIsu = stockIsu.toUpperCase();
    if (stockIsu == null) {
        return;
    }
    if (stockIsu === "") {
        return;
    }
    if (stockIsu.length == 6) {
        if ($c.num.isNumber($c.util.getComponent('ipt_stockIsu').getValue())) {
            $c.util.getComponent('ipt_stockIsuCd').setValue(stockIsu);
            $c.util.getComponent('ipt_stockIsuNm').setValue("");
            return;
        }
    }
    $c.util.getComponent('ipt_stockIsuCd').setValue("");
    $c.util.getComponent('ipt_stockIsuNm').setValue(stockIsu);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnShowKosdaqSeg
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.fnShowKosdaqSeg = function (obj) {
    /* sdd-asis-lifecycle:begin fnShowKosdaqSeg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (obj.val() === "2") {
        scwin.kosdaqSeg.setStyle("display", "");
    } else {
        scwin.kosdaqSeg.setStyle("display", "none");
    }
    $("#searchForm").find("input:radio[name=rd_kosdaqSegment]:input#rSeg").prop("checked", true);
    /* sdd-asis-lifecycle:end */
};
